mapper.select:
SELECT p.*,c.course_name,(SELECT COUNT(*) FROM exam_paper_question pq WHERE pq.paper_id=p.id) question_count
FROM exam_paper p JOIN sys_course c ON c.id=p.course_id

  AND p.course_id=#{courseId}
  AND p.stage_name=#{stageName}
  AND p.paper_name LIKE CONCAT('%',#{paperName},'%')

ORDER BY p.id DESC
